export const LINES={
  0:{zh:['你是新来的农夫吧?欢迎来到星星露谷。','今天湖面真平静。','有空常来镇上走走。','听说瀑布那边的鳟鱼很肥。','春天的第一场雨总让人想起故乡。'],en:['You must be the new farmer. Welcome to StarVale.','The lake is so calm today.','Come by town when you can.','They say the trout by the falls are fat this year.','The first spring rain always makes me think of home.']},
  2:{zh:['你的农场越来越有样子了。','能和你聊聊天真好。','湖边的日落,我看不腻。','下次来记得带点你种的东西。'],en:['Your farm is shaping up.','It is nice to chat with you.','I never tire of the sunsets on the lake.','Bring something you grew next time.']},
  5:{zh:['见到你总是很开心。','我把你当成真正的朋友了。','你改变了这个小镇,你知道吗?','来,这是给你留的。'],en:['It always makes me happy to see you.','I think of you as a real friend now.','You have changed this town, you know.','Here, I saved this for you.']},
  8:{zh:['不知怎么,看到你今天就亮了。','有些话,一直想对你说。','我们一起看过的日落,我都记得。'],en:['Somehow my day brightens when I see you.','There is something I keep wanting to tell you.','I remember every sunset we watched.']}
};

/* each villager's own voice: spoken lines by how well you know them (0, 2, 5, 8 hearts), and a scene at 2, 4, 6, 8 and 10 hearts. Scenes play where that person spends their day */
const say=(zh,en)=>({zh,en});
export const VOICE={
  mei:{0:say(['新来的?要什么种子尽管说。','周三店里休息,记得提前买。','春天的防风草最好上手。'],['New here? Tell me what seeds you need.','The shop shuts on Wednesdays, so plan ahead.','Parsnips are the easy start in spring.']),2:say(['你的田比上周又整齐了。','进货的车今天晚了点。'],['Your rows are straighter than last week.','The delivery is running late today.']),5:say(['我给你留了几包好种子,别告诉别人。','有时候我也想关了店去湖边坐坐。'],['I set aside some good seed for you. Keep it quiet.','Some days I want to shut the shop and sit by the lake.']),8:say(['你来了,今天就不算白过。','收银台后面太闷了,陪我走走?'],['You came by, so the day was not wasted.','It is stuffy behind this counter. Walk with me?']),ev:{2:{zh:'小梅把账本推到一边,给你看她画的店铺新招牌。',en:'Mei pushes the ledger aside and shows you a sketch for a new shop sign.',place:'store'},4:{zh:'下雨的午后店里没人,她煮了茶,说起第一次一个人进货的事。',en:'A rainy afternoon, empty shop. She makes tea and tells you about her first delivery alone.',place:'store'},6:{zh:'她把爷爷留下的旧秤擦得发亮:“他也总夸你种的东西。”',en:'She polishes the old scale your grandfather used. "He would have praised your crops too."',place:'store'},8:{zh:'打烊后她在门口等你,手里拎着两个苹果。',en:'After closing she waits by the door with two apples.',place:'plaza'},10:{zh:'她指着店门上的新招牌,角落里添了一颗小星星:“这是给你的。”',en:'She points to the new sign. A small star sits in the corner. "That one is yours."',place:'store'}}},
  ken:{0:say(['工具坏了就拿来。','别碰那个炉子,烫。','矿洞里小心点。'],['Bring me what breaks.','Keep off the forge, it is hot.','Watch yourself in the mine.']),2:say(['这把锄头用得不错,看得出来。','铜矿成色还行。'],['That hoe has seen honest use.','Decent copper, that.']),5:say(['你带来的矿,我都单独放着。','打铁这事,急不得。'],['I keep your ore in its own pile.','Iron cannot be hurried.']),8:say(['这镇上懂铁的人不多,你算一个。','来,握一下这把锤,感觉感觉。'],['Few here understand iron. You are one.','Take this hammer. Feel the weight.']),ev:{2:{zh:'阿健沉默地把一把修好的小刀推给你:“顺手的事。”',en:'Ken slides a mended knife across the anvil. "No trouble."',place:'smith'},4:{zh:'炉火映着他的脸,他说这座炉子是父亲一块砖一块砖砌的。',en:'By the firelight he says his father laid this forge brick by brick.',place:'smith'},6:{zh:'他让你敲下第一锤,火星溅了一地,他难得地笑了。',en:'He lets you strike the first blow. Sparks fly, and he actually smiles.',place:'smith'},8:{zh:'酒馆打烊后他一个人喝着啤酒,给你也推过来一杯。',en:'After the saloon closes he sits alone with a beer and pushes one your way.',place:'saloon'},10:{zh:'他把一枚亲手打的铁环放在你手心:“朋友的印记。”',en:'He sets a hand-forged iron ring in your palm. "A friend\'s mark."',place:'smith'}}},
  luna:{0:say(['挖到东西就拿来,我来鉴定。','博物馆还空着好多格子。'],['Bring what you dig up. I will identify it.','The museum has so many empty cases.']),2:say(['这片湖底下,比你想的更老。','你带来的箭头有三千年了。'],['This lake is older than you think.','That arrowhead of yours is three thousand years old.']),5:say(['我常常忘了吃饭,谢谢你提醒。','每件文物都有主人,只是他们都不在了。'],['I forget to eat. Thank you for reminding me.','Every artifact had an owner once.']),8:say(['闭馆之后,这里很安静,你愿意留一会儿吗?','我想把你的名字写进捐赠册的第一页。'],['After closing it is very quiet here. Will you stay a while?','I want your name on the first page of the donor book.']),ev:{2:{zh:'露娜让你戴上手套,一起给一块化石清灰。',en:'Luna hands you gloves and you brush dust from a fossil together.',place:'museum'},4:{zh:'她拿出放大镜,给你看紫水晶里的一道裂纹:“它比我们都老。”',en:'She shows you a flaw in an amethyst through her lens. "It is older than all of us."',place:'museum'},6:{zh:'傍晚在湖边,她说小时候以为星星是沉在水底的宝石。',en:'At dusk by the lake she says she once thought stars were gems sunk in the water.',place:'lake'},8:{zh:'她关掉展厅的灯,月光落在玻璃柜上,整间屋子都亮了。',en:'She turns off the gallery lights. Moonlight fills the glass cases.',place:'museum'},10:{zh:'她把一块小水晶放进你手里:“这件不捐,给你。”',en:'She closes your hand over a small crystal. "This one is not for the museum."',place:'museum'}}},
  tom:{0:say(['鱼不等人。','早晨的鱼最傻。','钓竿不是这么握的。'],['Fish wait for no one.','Morning fish are the dimmest.','You hold a rod like a shovel.']),2:say(['下雨天,鱼饿。','码头尽头水深,能钓到海里的家伙。'],['Rain makes them hungry.','Off the dock end it runs deep. Sea fish there.']),5:say(['你上钩的手法有点样子了。','我年轻时跑过船,那些事不提也罢。'],['Your strike is coming along.','I sailed when I was young. Best left alone.']),8:say(['这片水,我看了四十年,还是看不够。','来,这根浮标给你,我用不着了。'],['Forty years watching this water and it still holds me.','Here, this float. I will not need it.']),ev:{2:{zh:'老汤头也不抬,把一罐鱼饵放到你脚边。',en:'Tom does not look up. He sets a tin of bait by your feet.',place:'dock'},4:{zh:'天刚亮,他教你看水纹,说鱼都藏在影子里。',en:'At first light he teaches you to read the ripples. Fish hide in shadow.',place:'dock'},6:{zh:'他说起沉在外湾的那条船,和没回来的人。',en:'He talks about the boat sunk in the outer bay, and those who did not come back.',place:'dock'},8:{zh:'他把一根旧鱼竿递给你:“别弄丢了,是我师父的。”',en:'He hands you an old rod. "Do not lose it. It was my teacher\'s."',place:'fishshop'},10:{zh:'两个人坐到天黑,一句话也没说,却谁也不想走。',en:'You sit until dark without a word, and neither of you wants to leave.',place:'dock'}}},
  rosa:{0:say(['来杯什么?','今晚人多,自己找地方。'],['What will it be?','Busy tonight. Find a seat.']),2:say(['你看起来累坏了,吃点东西吧。','我记得你爱喝什么。'],['You look spent. Eat something.','I remember what you drink.']),5:say(['酒馆里的秘密,我都听过。','你比大多数人都懂礼貌。'],['I have heard every secret this bar holds.','You have better manners than most.']),8:say(['这杯算我的,不用客气。','有你在,这里才像个家。'],['This one is on me.','With you around it feels like home in here.']),ev:{2:{zh:'蔷薇把一盘刚出炉的披萨放到你面前:“试菜,别说出去。”',en:'Rosa sets down a fresh pizza. "Test batch. Keep it quiet."',place:'saloon'},4:{zh:'打烊时她一边擦杯子,一边讲起她是怎么接下这家店的。',en:'Closing up, she polishes glasses and tells you how the saloon became hers.',place:'saloon'},6:{zh:'她把一本旧菜谱翻开,上面全是她母亲的字迹。',en:'She opens an old recipe book, full of her mother\'s handwriting.',place:'saloon'},8:{zh:'全镇都在跳舞,她却在吧台后面看着你笑。',en:'The whole town is dancing, and she smiles at you from behind the bar.',place:'saloon'},10:{zh:'她在墙上最好的位置,钉上了你第一次来时留下的硬币。',en:'On the best spot of the wall she pins the coin you left on your first night.',place:'saloon'}}},
  hal:{0:say(['要盖东西就说。','木头要晾透才好用。'],['Tell me what you want built.','Timber must dry before it serves.']),2:say(['你那块地的排水不错。','好木匠看纹路。'],['Good drainage on your land.','A carpenter reads the grain.']),5:say(['我量过你家门框,歪了两分。','有空来帮我扶一下梁。'],['I measured your door frame. Two fingers off.','Come hold a beam for me some time.']),8:say(['我在做一把椅子,是按你的身高做的。','你手上有茧了,像我们这行的。'],['I am making a chair to your measure.','You have calluses now, like one of us.']),ev:{2:{zh:'阿哈递给你一块刨花,闻起来像春天。',en:'Hal hands you a curl of wood shaving. It smells of spring.',place:'carpenter'},4:{zh:'你们一起把一根大梁抬上架子,他拍拍你的肩。',en:'You lift a great beam onto the rack together. He claps your shoulder.',place:'carpenter'},6:{zh:'他带你看山上那片老林子,说镇上的房子都是从这里来的。',en:'He shows you the old wood on the hill, where every house in town came from.',place:'carpenter'},8:{zh:'他把那把椅子搬到你家门口,什么也没说就走了。',en:'He carries the chair to your door and leaves without a word.',place:'carpenter'},10:{zh:'他在你的小屋门楣上刻了一颗星。',en:'He carves a star above your cabin door.',place:'carpenter'}}},
  nan:{0:say(['动物比人老实。','牛要摸,鸡要哄。'],['Animals are more honest than people.','Cows want petting, hens want coaxing.']),2:say(['你家的鸡下蛋了吧?','别忘了存草。'],['Your hens laying yet?','Do not forget the hay.']),5:say(['你养的动物眼神都亮,说明过得好。','我给小牛接生的时候,手都在抖。'],['Your animals have bright eyes. They live well.','My hands shook the first calf I delivered.']),8:say(['这片牧场以后想交给懂的人。','和你说话比和牛说话有意思一点。'],['I want this ranch to go to someone who understands it.','You talk a little better than the cows.']),ev:{2:{zh:'南希教你挑草料,说闻起来甜的才是好的。',en:'Nan shows you how to pick hay. If it smells sweet, it is good.',place:'ranch'},4:{zh:'半夜一头牛要生了,你举着灯陪她守到天亮。',en:'A cow calves at night. You hold the lamp with her until dawn.',place:'ranch'},6:{zh:'她给你看墙上的旧照片:年轻时的她骑在马上。',en:'She shows you an old photo of herself, young, on horseback.',place:'ranch'},8:{zh:'她把最好的一块奶酪切给你:“别人我不给。”',en:'She cuts you the best of the cheese. "No one else gets this."',place:'ranch'},10:{zh:'她说:“这片地的动物,都认得你的脚步声了。”',en:'"Every animal on this land knows your footstep now," she says.',place:'ranch'}}},
  pip:{0:say(['你是新来的!你会抓虫吗?','我知道一个秘密基地!'],['You are the new one! Can you catch bugs?','I know a secret base!']),2:say(['给你看我的石头,这块最圆。','老师说我话太多。'],['Look at my stones. This one is the roundest.','Teacher says I talk too much.']),5:say(['长大了我要去矿洞打怪!','你今天带糖了吗?'],['When I grow up I will fight in the mine!','Got any sweets today?']),8:say(['你是我最好的大朋友。','我把我的秘密基地地图画给你了。'],['You are my best big friend.','I drew you the map to my secret base.']),ev:{2:{zh:'小皮拉着你看他养在罐子里的甲虫。',en:'Pip drags you over to see a beetle in a jar.',place:'plaza'},4:{zh:'他在河边打水漂,硬要你比一比。',en:'He skips stones on the river and insists you compete.',place:'river'},6:{zh:'他难过地告诉你,甲虫飞走了。你陪他坐了一会儿。',en:'He tells you sadly that the beetle flew off. You sit with him a while.',place:'plaza'},8:{zh:'他送你一张画:小屋、星星人,还有他自己。',en:'He gives you a drawing: the cabin, the star figure, and himself.',place:'plaza'},10:{zh:'他认真地说:“你是这个镇上最厉害的人。”',en:'"You are the coolest person in town," he says, very seriously.',place:'plaza'}}},
  ivy:{0:say(['别逞强,累了就睡。','定期体检是好习惯。'],['Do not push it. Sleep when you are tired.','Regular check-ups are a good habit.']),2:say(['你脸色比上周好。','矿洞里受伤了要来。'],['You look better than last week.','If the mine hurts you, come in.']),5:say(['我有时候也想找个人说说话。','你带来的甜瓜,我吃了一整个。'],['I want someone to talk to sometimes too.','I ate that whole melon you brought.']),8:say(['关诊所之后,我常想起你。','别受伤,我不想在这里见到你。'],['After closing, I find I think of you.','Do not get hurt. I do not want to see you here.']),ev:{2:{zh:'艾薇给你量了血压,又偷偷塞给你一颗糖。',en:'Ivy takes your blood pressure and slips you a sweet.',place:'clinic'},4:{zh:'病人都走了,她累得趴在桌上,你替她关了灯。',en:'The last patient gone, she falls asleep at the desk. You turn off the lamp.',place:'clinic'},6:{zh:'湖边她说起第一次一个人值夜班。',en:'By the lake she tells you about her first night shift alone.',place:'lake'},8:{zh:'她握住你的手腕数脉搏,数着数着就笑了。',en:'She counts your pulse at the wrist, then starts to laugh.',place:'clinic'},10:{zh:'她说:“以后你的病历,我亲自写。”',en:'"From now on I write your chart myself," she says.',place:'clinic'}}},
  leo:{0:say(['欢迎来到星星露谷。','广场的节日可别错过。'],['Welcome to StarVale.','Do not miss the festivals in the square.']),2:say(['镇子靠大家撑着。','你的出货量不错。'],['A town is held up by everyone in it.','Good shipping numbers.']),5:say(['社区中心的事,就拜托你了。','你爷爷当年也坐在这里。'],['I am counting on you for the Community Centre.','Your grandfather used to sit right here.']),8:say(['我老了,镇子以后要靠你们。','有你在,我放心。'],['I am old. The town will need you.','With you here I can rest easy.']),ev:{2:{zh:'里奥带你看广场的老照片,那时候这里还是一片芦苇。',en:'Leo shows you an old photo of the square, when it was only reeds.',place:'plaza'},4:{zh:'他请你喝一杯,说镇长这份工作最难的是记住所有人的生日。',en:'Over a drink he says the hardest job of a mayor is remembering birthdays.',place:'saloon'},6:{zh:'他说起你爷爷帮他竞选的事,眼眶有点红。',en:'He tells you how your grandfather helped him win. His eyes grow wet.',place:'plaza'},8:{zh:'他把一把旧钥匙给你:“镇史馆的,你比我更该留着。”',en:'He hands you an old key. "To the town archive. You should keep it now."',place:'plaza'},10:{zh:'他在全镇面前谢了你,你第一次看到他讲不下去。',en:'He thanks you before the whole town, and for once he cannot finish.',place:'plaza'}}},
  sora:{0:say(['别挡光。','瀑布今天的颜色不对。'],['You are in my light.','The falls are the wrong colour today.']),2:say(['你衣服的颜色还行。','我在画你家那片田。'],['Your clothes are a passable colour.','I am painting your fields.']),5:say(['你站在那儿别动,这个光好看。','我总是调不出湖水的绿。'],['Stay there. The light is good.','I can never mix the green of the lake.']),8:say(['这幅画没有卖,是给你的。','想把今天的你画下来。'],['This painting is not for sale. It is for you.','I want to paint you as you are today.']),ev:{2:{zh:'空把一支笔塞给你,让你也试试。',en:'Sora puts a brush in your hand and tells you to try.',place:'falls'},4:{zh:'瀑布边他们一句话不说地画了一下午,你在旁边看着。',en:'An afternoon by the falls, painting without a word as you watch.',place:'falls'},6:{zh:'空把一张撕掉的画拼回去:“这张,我不满意的是我自己。”',en:'Sora tapes a torn canvas back together. "It was me I was unhappy with."',place:'plaza'},8:{zh:'画布上是你的小屋,灯亮着。',en:'On the canvas: your cabin, with the lamp lit.',place:'falls'},10:{zh:'那幅画挂在了你家墙上,角落写着你的名字。',en:'The painting hangs on your wall, your name in the corner.',place:'falls'}}},
  finn:{0:say(['要过湖吗?','风要变了。'],['Crossing the lake?','The wind is turning.']),2:say(['灯塔那边的路不好走。','你划船的姿势还行。'],['The lighthouse path is rough.','You row well enough.']),5:say(['夜里的湖面最好看。','我听过灯塔下的鲸歌,没人信。'],['The lake is best at night.','I have heard whale song under the lighthouse. No one believes me.']),8:say(['下次出湖,带上你。','风大的时候,我会想起你说的话。'],['Next time I go out, you come along.','When the wind is high I think of what you said.']),ev:{2:{zh:'阿芬教你打一个水手结。',en:'Finn teaches you a sailor\'s knot.',place:'dock'},4:{zh:'你们划到湖心,他关了灯,让你看水里的星星。',en:'You row to the middle. He douses the lamp so you can see the stars in the water.',place:'dock'},6:{zh:'他说起离开这里的那些年,和最后为什么回来。',en:'He tells you about the years away, and why he came back.',place:'lighthousePath'},8:{zh:'灯塔的灯亮起来,他站在你身边没有说话。',en:'The lighthouse lamp comes on. He stands beside you in silence.',place:'lighthousePath'},10:{zh:'他把船头新写的名字指给你看,那是你的名字。',en:'He points to the new name on the bow. It is yours.',place:'dock'}}}
};
